package io.fireflysoftware.common.config.web.tenantbinding;

import io.fireflysoftware.common.config.core.authority.*;
import io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingContracts.*;
import io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingGovernedContracts.*;
import io.fireflysoftware.common.config.web.controllers.authority.TenantResourceBindingGovernanceController;
import io.fireflysoftware.common.config.web.tenantbinding.impl.TenantResourceBindingGovernanceBudgetFilterImpl;
import io.fireflysoftware.common.config.web.tenantbinding.impl.TenantResourceBindingGovernanceRequestCodecImpl;
import org.fireflyframework.core.transaction.R2dbcOperationBudget;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.http.MediaType;
import org.springframework.test.web.reactive.server.WebTestClient;
import reactor.core.publisher.Mono;
import java.time.*;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class TenantResourceBindingGovernanceHttpTest {
    static final String BASE="/api/v1/tenant-resource-bindings/governance";
    static final Intent INTENT=new Intent(Kind.CONTROL,null,null,new Command(UUID.fromString("00000000-0000-0000-0000-000000000011"),UUID.fromString("00000000-0000-0000-0000-000000000012"),Operation.TENANT_RESOURCE_BINDING_ESTABLISH,new Definition(UUID.fromString("00000000-0000-0000-0000-000000000013"),new Namespace("https://verified.example.test","opaque / platform"),new ResourceTenant(UUID.fromString("00000000-0000-0000-0000-000000000014")),1,new Eligibility(0,UUID.fromString("00000000-0000-0000-0000-000000000015"),0),Instant.parse("2026-11-02T00:00:00Z").toEpochMilli()),new Eligibility(0,UUID.fromString("00000000-0000-0000-0000-000000000015"),0),0));
    static final ActionRequest REQUEST=new ActionRequest(INTENT,TenantResourceBindingGovernedCodec.digest(INTENT));
    static String json(Object value){try{return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(value);}catch(Exception error){throw new AssertionError(error);}}
    static final class Fixture {
        final TenantResourceBindingGovernedActions service=mock(TenantResourceBindingGovernedActions.class);
        final AtomicInteger calls=new AtomicInteger();
        WebTestClient client(boolean originalFilter){return client(originalFilter,Clock.systemUTC(),System::nanoTime);}
        @SuppressWarnings("unchecked") WebTestClient client(boolean originalFilter,Clock clock,java.util.function.LongSupplier nanos){var provider=(ObjectProvider<TenantResourceBindingGovernedActions>)mock(ObjectProvider.class);when(provider.getIfAvailable()).thenReturn(service);var binding=WebTestClient.bindToController(new TenantResourceBindingGovernanceController(provider));if(originalFilter)binding.webFilter(new TenantResourceBindingGovernanceBudgetFilterImpl(clock,nanos));return binding.build();}
    }
    @Test void missingOriginalIngressBudgetCannotReachAnOwner(){var f=new Fixture();f.client(false).post().uri(BASE+"/intents").contentType(MediaType.APPLICATION_JSON).bodyValue(INTENT).exchange().expectStatus().isEqualTo(503);verifyNoInteractions(f.service);}
    @Test void unknownNestedBodyAuthorityIsRejectedBeforeAnyOwnerCall(){var f=new Fixture();String body="{\"kind\":\"CONTROL\",\"control\":"+json(INTENT.control()).replace("\"expectedControlVersion\":0","\"staffActorId\":\"forged\",\"expectedControlVersion\":0")+"}";f.client(true).post().uri(BASE+"/intents").contentType(MediaType.APPLICATION_JSON).bodyValue(body).exchange().expectStatus().isBadRequest();verifyNoInteractions(f.service);}
    @Test void readOnlyIntentReturnsTheOwnerDigestWithoutACommand(){var f=new Fixture();when(f.service.prepareIntent(eq(INTENT),any())).thenReturn(Mono.just(new PreparedIntent(INTENT.control().actionId(),REQUEST.originalIntentDigest())));f.client(true).post().uri(BASE+"/intents").contentType(MediaType.APPLICATION_JSON).bodyValue(INTENT).exchange().expectStatus().isOk().expectHeader().valueMatches("Cache-Control",".*no-store.*").expectBody().jsonPath("$.actionId").isEqualTo(INTENT.control().actionId().toString()).jsonPath("$.intentDigest").isEqualTo(REQUEST.originalIntentDigest());verify(f.service).prepareIntent(eq(INTENT),any(R2dbcOperationBudget.class));verifyNoMoreInteractions(f.service);}
    @Test void unknownOutcomeKeepsTheOriginalIdentityAndNoProtectedResult(){var f=new Fixture();when(f.service.execute(eq(REQUEST),any())).thenReturn(Mono.just(new ActionResult(ActionStatus.OUTCOME_UNKNOWN,INTENT.control().actionId(),REQUEST.originalIntentDigest(),null,null)));f.client(true).post().uri(BASE+"/actions").contentType(MediaType.APPLICATION_JSON).bodyValue(REQUEST).exchange().expectStatus().isOk().expectBody().jsonPath("$.status").isEqualTo("OUTCOME_UNKNOWN").jsonPath("$.actionId").isEqualTo(INTENT.control().actionId().toString()).jsonPath("$.intentDigest").isEqualTo(REQUEST.originalIntentDigest());verify(f.service,times(1)).execute(eq(REQUEST),any());verifyNoMoreInteractions(f.service);}
    @Test void responseLossAfterDispatchNeverTriggersAnAutomaticReplacement(){var f=new Fixture();when(f.service.execute(eq(REQUEST),any())).thenReturn(Mono.error(new IllegalStateException("private failure")));f.client(true).post().uri(BASE+"/actions").contentType(MediaType.APPLICATION_JSON).bodyValue(REQUEST).exchange().expectStatus().isOk().expectBody().jsonPath("$.status").isEqualTo("OUTCOME_UNKNOWN").jsonPath("$.intentDigest").isEqualTo(REQUEST.originalIntentDigest());verify(f.service,times(1)).execute(eq(REQUEST),any());verifyNoMoreInteractions(f.service);}
    @Test void aCommittedOwnerResultWhoseResponseBudgetExpiresCannotBeDowngradedToUnknown(){var f=new Fixture();var time=new TenantResourceBindingGovernanceBudgetTest.Time();var completion=new Completion(INTENT.control().actionId(),REQUEST.originalIntentDigest(),TenantResourceBindingCodec.reference(INTENT.control().definition()),1,State.ACTIVE,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID());when(f.service.execute(eq(REQUEST),any())).thenReturn(Mono.just(new ActionResult(ActionStatus.COMMITTED,INTENT.control().actionId(),REQUEST.originalIntentDigest(),null,completion)).doOnNext(ignored->time.advance(5000)));f.client(true,time,()->time.nanos).post().uri(BASE+"/actions").contentType(MediaType.APPLICATION_JSON).bodyValue(REQUEST).exchange().expectStatus().isOk().expectBody().jsonPath("$.status").isEqualTo("COMMITTED_RESPONSE_UNAVAILABLE").jsonPath("$.intentDigest").isEqualTo(REQUEST.originalIntentDigest()).jsonPath("$.completion").doesNotExist();verify(f.service,times(1)).execute(eq(REQUEST),any());verifyNoMoreInteractions(f.service);}
    @Test void recoveryReadsOriginalActionAndDoesNotDispatchCommand(){var f=new Fixture();when(f.service.recover(eq(REQUEST),any())).thenReturn(Mono.just(new Recovery(RecoveryStatus.NOT_OBSERVED_AT_THIS_READ,INTENT.control().actionId(),REQUEST.originalIntentDigest(),null)));f.client(true).post().uri(BASE+"/actions/observations").contentType(MediaType.APPLICATION_JSON).bodyValue(REQUEST).exchange().expectStatus().isOk().expectBody().jsonPath("$.status").isEqualTo("NOT_OBSERVED_AT_THIS_READ");verify(f.service).recover(eq(REQUEST),any());verifyNoMoreInteractions(f.service);}
    @Test void malformedDuplicateAndMissingControlExpectationsCannotDefaultToAnAdmittedWrite(){String body=json(INTENT);assertThrows(IllegalArgumentException.class,()->TenantResourceBindingGovernanceRequestCodecImpl.intent(body.replace("\"expectedControlVersion\":0", "\"expectedControlVersion\":0,\"expectedControlVersion\":0").getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertThrows(IllegalArgumentException.class,()->TenantResourceBindingGovernanceRequestCodecImpl.intent(body.replace(",\"expectedControlVersion\":0", "").getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
    @Test void generatedNullableBranchesMayBeAbsentButCannotSelectTwoOperations(){String body=json(INTENT).replace("\"preparation\":null,", "").replace("\"decision\":null,", "");assertEquals(INTENT,TenantResourceBindingGovernanceRequestCodecImpl.intent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertThrows(IllegalArgumentException.class,()->TenantResourceBindingGovernanceRequestCodecImpl.intent(body.replace("\"kind\":\"CONTROL\"","\"kind\":\"DECISION\"").getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
}
